<script module lang="ts">
/**
 * Token-styled scrollbar for a region that already scrolls (`design/components/scroll-area.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scroll-area.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import * as zag from '@zag-js/scroll-area'
import { useMachine } from '@zag-js/svelte'

import { attributes, joinSlot, normalizeProps, useDirection } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/scroll-area.module.css'

export type ScrollAreaOrientation = NonNullable<ScrollAreaProps['orientation']>

export type ScrollAreaType = NonNullable<ScrollAreaProps['type']>

export interface ScrollAreaProps {
  /**
   * The region's content; the consumer sets the region's *size* (a Table port's width, a panel's
   * height), and ScrollArea fills the box it is given.
   */
  children: Snippet
  /**
   * Names the region for keyboard users once it overflows, as in CodeBlock. Required rather than
   * defaulted. The content identifies the region, but a default name would be in one fixed
   * language, and the app's language is unknown here.
   */
  label: string
  /**
   * Which axes may pan; `'both'` draws two rails and the corner.
   */
  orientation?: 'horizontal' | 'vertical' | 'both'
  type?: 'hover' | 'always'
}
</script>

<script lang="ts">
let {
  children,
  label: labelOwn,
  orientation = 'vertical',
  type = 'always',
}: ScrollAreaProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const fades = $derived(type === 'hover')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () => ({ id: uid, dir: documentDirection.current }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const overflowing = $derived(api.hasOverflowX || api.hasOverflowY)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div {...attributes(api.getRootProps())} class={styles.root} data-member="scroll-area"
    ><div
      {...attributes(api.getViewportProps())}
      class={styles.viewport}
      style:overflow-x={orientation === 'vertical' ? 'hidden' : 'scroll'}
      style:overflow-y={orientation === 'horizontal' ? 'hidden' : 'scroll'}
      style:scrollbar-width={'none'}
      tabindex={((overflowing) ? 0 : undefined) as never}
      role={(overflowing) ? 'region' : undefined}
      aria-label={(overflowing) ? label : undefined}
      ><div {...attributes(api.getContentProps())}>{@render children?.()}</div
    ></div
    >{#if orientation === 'both' || orientation === 'vertical'
      }{#if api.hasOverflowY
        }<div
          {...attributes(api.getScrollbarProps({ orientation: 'vertical' }))}
          class={[styles.rail, fades ? styles.hover : undefined, !fades ? styles.always : undefined]}
          aria-hidden="true"
          data-state={(fades) ? api.getScrollbarState({ orientation: 'vertical' }).hovering || api.getScrollbarState({ orientation: 'vertical' }).scrolling ? 'visible' : 'hidden' : undefined}
          ><div {...attributes(api.getThumbProps({ orientation: 'vertical' }))} class={styles.thumb}></div
        ></div
      >{/if
    }{/if
    }{#if orientation === 'both' || orientation === 'horizontal'
      }{#if api.hasOverflowX
        }<div
          {...attributes(api.getScrollbarProps({ orientation: 'horizontal' }))}
          class={[styles.rail, fades ? styles.hover : undefined, !fades ? styles.always : undefined]}
          aria-hidden="true"
          data-state={(fades) ? api.getScrollbarState({ orientation: 'horizontal' }).hovering || api.getScrollbarState({ orientation: 'horizontal' }).scrolling ? 'visible' : 'hidden' : undefined}
          ><div
            {...attributes(api.getThumbProps({ orientation: 'horizontal' }))}
            class={styles.thumb}
          ></div
        ></div
      >{/if
    }{/if
    }{#if orientation === 'both'
      }<div {...attributes(api.getCornerProps())} class={styles.corner} aria-hidden="true"></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
